"use client";
import {useEffect,useMemo,useState} from "react";
import PageTitle from "@/composants/ui/PageTitle";import Section from "@/composants/ui/Section";import Input from "@/composants/ui/Input";import Alert from "@/composants/ui/Alert";import {serviceFinance} from "@/services/ServiceFinance.js";import {serviceAdministration} from "@/services/ServiceAdministration.js";
export default function Page(){const[data,setData]=useState({invoices:[]});const[merchants,setMerchants]=useState([]);const[selected,setSelected]=useState([]);const[selectedInvoices,setSelectedInvoices]=useState([]);const[period,setPeriod]=useState("Juillet 2026");const[feedback,setFeedback]=useState(null);async function refresh(){try{const[d,m]=await Promise.all([serviceFinance.getAll(),serviceAdministration.listUsers({role:'commercant',statutCompte:'actif',limit:100})]);setData(d);setMerchants(m)}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de charger les factures."})}}useEffect(()=>{refresh()},[]);const all=merchants.length>0&&selected.length===merchants.length;const unpaid=useMemo(()=>data.invoices?.filter(i=>i.status!=="payee")||[],[data]);const allUnpaid=unpaid.length>0&&selectedInvoices.length===unpaid.length;function toggle(id){setSelected(x=>x.includes(id)?x.filter(v=>v!==id):[...x,id])}function toggleInvoice(id){setSelectedInvoices(x=>x.includes(id)?x.filter(v=>v!==id):[...x,id])}async function generate(ids){try{setFeedback(null);const r=await serviceFinance.createInvoicesBulk(period,ids);setFeedback({type:"success",message:`${r.total} facture(s) générée(s)${r.skipped?.length?` · ${r.skipped.length} déjà existante(s)`:''}.`});setSelected([]);await refresh()}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de générer les factures."})}}async function paid(id){try{await serviceFinance.updateInvoice(id,"payee");setSelectedInvoices(x=>x.filter(v=>v!==id));await refresh()}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de mettre à jour la facture."})}}async function paidBulk(ids){try{setFeedback(null);const r=await serviceFinance.updateInvoicesBulk(ids,"payee");setFeedback({type:"success",message:`${r.total} facture(s) marquée(s) payée(s).`});setSelectedInvoices([]);await refresh()}catch(error){setFeedback({type:"error",message:error?.message||"Impossible de valider les paiements."})}}return <div className="space-y-8"><PageTitle title="Factures commerçants" description="Générez les factures en groupe puis validez plusieurs paiements en une seule action."/>{feedback&&<Alert type={feedback.type} message={feedback.message}/>}<Section title="Génération groupée"><div className="max-w-md"><Input label="Période" name="period" value={period} onChange={e=>setPeriod(e.target.value)}/></div><div className="mt-5 flex flex-wrap gap-3"><button onClick={()=>generate([])} className="rounded-xl bg-indigo-600 px-5 py-3 text-sm font-bold text-white">Générer pour tous les commerçants actifs</button><button disabled={!selected.length} onClick={()=>generate(selected)} className="rounded-xl border border-slate-300 px-5 py-3 text-sm font-bold text-slate-700 disabled:opacity-40">Générer la sélection ({selected.length})</button></div><div className="mt-5 overflow-hidden rounded-2xl border border-slate-200"><label className="flex items-center gap-3 border-b border-slate-200 bg-white/70 p-4 text-sm font-bold"><input type="checkbox" checked={all} onChange={()=>setSelected(all?[]:merchants.map(m=>m.id))}/> Tout sélectionner</label>{merchants.map(m=><label key={m.id} className="flex items-center gap-3 border-b border-slate-200 p-4 text-sm last:border-0"><input type="checkbox" checked={selected.includes(m.id)} onChange={()=>toggle(m.id)}/><span className="font-semibold">{m.name}</span><span className="text-slate-600">{m.email}</span></label>)}</div></Section><Section title="Validation des paiements" description="La plateforme ne peut pas deviner qu’un paiement bancaire a réellement été reçu : la validation reste une action financière, mais elle peut être faite en lot."><div className="mb-4 flex flex-wrap gap-3"><button disabled={!unpaid.length} onClick={()=>paidBulk(unpaid.map(i=>i.id))} className="rounded-xl bg-indigo-600 px-5 py-3 text-sm font-bold text-white disabled:opacity-40">Marquer toutes les factures en attente comme payées</button><button disabled={!selectedInvoices.length} onClick={()=>paidBulk(selectedInvoices)} className="rounded-xl border border-slate-300 px-5 py-3 text-sm font-bold text-slate-700 disabled:opacity-40">Valider la sélection ({selectedInvoices.length})</button></div><label className="mb-3 flex items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm font-bold"><input type="checkbox" checked={allUnpaid} disabled={!unpaid.length} onChange={()=>setSelectedInvoices(allUnpaid?[]:unpaid.map(i=>i.id))}/> Sélectionner toutes les factures en attente</label><div className="space-y-3">{data.invoices?.map(i=><div key={i.id} className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-slate-50 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3">{i.status!=="payee"&&<input className="mt-1" type="checkbox" checked={selectedInvoices.includes(i.id)} onChange={()=>toggleInvoice(i.id)}/>}<div><p className="font-bold">{i.merchant}</p><p className="mt-1 text-sm text-slate-600">{i.period} · {Number(i.amount).toFixed(2)} €</p></div></div><div className="flex items-center gap-3"><span className="rounded-full px-3 py-1 text-xs font-bold">{i.status}</span>{i.status!=="payee"&&<button onClick={()=>paid(i.id)} className="text-xs font-bold text-blue-700">Marquer payée</button>}</div></div>)}</div></Section></div>}
